(function(root){
const HEADERS=['ID','Action','Category','Keys','Assignment','Scope','Review','Kind','Notes','Sources','Parent ID'];
function normalize(s){return String(s).toLowerCase().replaceAll('⌘','cmd').replaceAll('command','cmd').replaceAll('⌥','alt').replaceAll('option','alt').replaceAll('⇧','shift').replaceAll('⌃','ctrl').replaceAll('control','ctrl').replaceAll('↑','up').replaceAll('↓','down').replaceAll('←','left').replaceAll('→','right').replace(/\s*\+\s*/g,'+').trim()}
function splitShortcut(s){let key=normalize(s),modifiers=[];let m;while((m=/^(cmd|alt|ctrl|shift)\+/.exec(key))){modifiers.push(m[1]);key=key.slice(m[0].length)}return {key,modifiers:[...new Set(modifiers)].sort()}}
function matchesShortcut(combo,key,modifiers,allModifiers=false){const c=splitShortcut(combo);return (!key||c.key===normalize(key))&&(allModifiers||c.modifiers.join('|')===[...modifiers].sort().join('|'))}
function activeSectionIndex(bottoms,edge){const index=bottoms.findIndex(bottom=>bottom>edge);return index<0?Math.max(0,bottoms.length-1):index}
function uniqueKeys(keys){const seen=new Set();return keys.split(';').map(k=>k.trim()).filter(k=>{const n=normalize(k);if(!k||seen.has(n))return false;seen.add(n);return true})}
function filter(rows,q){const words=normalize(q.search||'').split(/\s+/).filter(Boolean),keys=normalize(q.keys||'');return rows.filter(r=>words.every(w=>normalize([r.Action,r.Category,r.Keys].join(' ')).includes(w))&&(!q.category||r.Category===q.category)&&(!keys||r.Keys.split(';').some(k=>normalize(k)===keys))&&(!(q.modifiers?.length||q.baseKey)||r.Keys.split(';').some(k=>matchesShortcut(k,q.baseKey,q.modifiers||[],q.allModifiers)))&&(!q.assignment||r.Assignment===q.assignment)&&(!q.review||r.Review==='Needs review'))}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let grid=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||cell===''){quoted=!quoted}else throw Error('Unexpected quote in CSV. Export the Catalog tab again.')}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))grid.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV has an unfinished quoted field.');row.push(cell);if(row.some(x=>x!==''))grid.push(row);if(grid.length<2)throw Error('CSV needs headers and at least one action.');const header=grid.shift().map(x=>x.trim());if(HEADERS.filter(h=>h!=='Parent ID').some(h=>!header.includes(h))||new Set(header).size!==header.length)throw Error('Export the Catalog tab with its original column headers.');const ids=new Set();return grid.map((cells,i)=>{if(cells.length!==header.length)throw Error(`Row ${i+2} has the wrong number of columns.`);const r=Object.fromEntries(HEADERS.map(h=>[h,cells[header.indexOf(h)]||'']));if(!r.ID||ids.has(r.ID)||!r.Action||!r.Category)throw Error(`Row ${i+2} needs a unique ID, action and category.`);ids.add(r.ID);if(!['Assigned','Unassigned','Not visible','Not applicable'].includes(r.Assignment)||!['Needs review','Transcribed'].includes(r.Review)||!['Action','Collapsed group','Group'].includes(r.Kind))throw Error(`Row ${i+2} has an unsupported status or kind.`);if(r.Assignment==='Assigned'&&!r.Keys.trim())throw Error(`Row ${i+2} is Assigned but has no keys.`);if(r.Assignment==='Unassigned'&&r.Keys.trim())throw Error(`Row ${i+2} is Unassigned but has keys.`);return r})}
function csv(rows){const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [HEADERS,...rows.map(r=>HEADERS.map(h=>r[h]))].map(r=>r.map(quote).join(',')).join('\r\n')+'\r\n'}
root.CatalogCore={HEADERS,activeSectionIndex,normalize,splitShortcut,matchesShortcut,uniqueKeys,filter,parseCSV,csv};if(typeof module!=='undefined')module.exports=root.CatalogCore;
})(typeof window!=='undefined'?window:globalThis);
